'use strict';
function configureLessons(){const data={
queries:{topic:'ROWS, PAGES & INDEXES',title:'Ask less of the disk.<br><em>Get the same answer.</em>',intro:'A query describes the answer you want. PostgreSQL chooses how to find it. An index can change the work without changing the result.',time:'6 MIN',question:'Why did the demo’s query become faster after adding an index?',answers:['Forklift replaced PostgreSQL’s query engine.','PostgreSQL could find a small set of matching values with less scanning.','The database stopped writing its recovery log.'],correct:1,explanation:'This is ordinary PostgreSQL indexing. Forklift provided an isolated place to test it. The recorded query speedup belongs to this query and fixture.'},
transactions:{topic:'TRANSACTIONS & WAL',title:'A change is easy.<br><em>A promise is harder.</em>',intro:'A database must do more than remember values. It must keep a meaningful promise when a process crashes halfway through a change.',time:'6 MIN',question:'The commit is durable, but a changed data page hasn’t reached disk. Then PostgreSQL crashes. What helps?',answers:['PostgreSQL replays the required WAL records during recovery.','Forklift merges the branch with its sibling.','The transaction must always be lost.'],correct:0,explanation:'WAL records reach durable storage before the corresponding data pages. Recovery can redo logged changes. Transaction status controls visibility; recovery does not make uncommitted transactions visible.'},
cow:{topic:'FILESYSTEM COPY-ON-WRITE',title:'Separate files.<br><em>Shared beginnings.</em>',intro:'A full copy duplicates every byte. An APFS clone creates an independent file that can initially share physical storage with its source.',time:'5 MIN',question:'Does APFS cloning make today’s cached Forklift branch operation constant-time?',answers:['Yes, because no bytes are ever read.','No. Forklift still reads and hashes the complete cached files.','Yes, as long as the branch is parked.'],correct:1,explanation:'The clone avoids a full byte copy, but the cache verification scans the entire materialization. End-to-end fork cost still grows with the saved content.'},
objects:{topic:'CHECKPOINTS, HASHES & CACHE',title:'Save the ingredients.<br><em>Keep the recipe.</em>',intro:'A portable checkpoint is a manifest plus immutable compressed packs. A cache turns that recipe back into the ordinary files PostgreSQL needs.',time:'7 MIN',question:'A cache hit works, but an object pack is missing. Can an export still succeed?',answers:['Yes, because the cache proves every pack exists.','No. Export independently needs and verifies the object contents.','Only if you disable PostgreSQL fsync.'],correct:1,explanation:'The verified cache is a local optimization. A cache hit checks cached files, not every original object pack. Export and direct reconstruction must read their required objects.'},
lifecycle:{topic:'PERSISTENT STATE & ACTIVE COMPUTE',title:'A hundred experiments.<br><em>Only a few engines.</em>',intro:'Files can wait on disk without a running server. Forklift separates the experiments you keep from the computation you activate.',time:'5 MIN',question:'You have 100 parked branches. How many PostgreSQL servers are they running?',answers:['100: each branch needs a permanent process.','3: the default limit always keeps three alive.','0: parked means files, with no running server.'],correct:2,explanation:'The default limit is a maximum of three active clusters per store, not a minimum. Starting a branch is explicit. Each active cluster can have multiple PostgreSQL processes.'},
recovery:{topic:'CATALOGS & ATOMIC PUBLICATION',title:'Build the replacement.<br><em>Then change the pointer.</em>',intro:'Reset must not leave a half-old, half-new database. Forklift prepares a separate generation, then changes which generation the branch selects.',time:'7 MIN',question:'Forklift dies before the catalog switch during reset. Which generation should recovery select?',answers:['The new one, even if it is incomplete.','The old one: the replacement has not been published.','Whichever directory has the newest file.'],correct:1,explanation:'The catalog is authoritative. Before publication, the old generation stays selected. After publication, the replacement stays selected. Recovery resumes the selected generation when appropriate.'},
code:{topic:'A GUIDED SOURCE TOUR',title:'Read the machinery.<br><em>One boundary at a time.</em>',intro:'You don’t need to know all of Rust to follow Forklift. Start with what each module owns, then learn the few language features that make the protocol visible.',time:'8 MIN',question:'What does the question mark in f.sync_all()? mean?',answers:['Ignore any filesystem error and keep going.','Return early if synchronization fails; otherwise continue.','Make the write happen in a background thread.'],correct:1,explanation:'The ? operator propagates an error from a Result. It keeps failures explicit, but Rust still cannot prove that you chose the correct storage ordering.'},
evidence:{topic:'MEASUREMENTS & LIMITS',title:'A working prototype.<br><em>Evidence, not mythology.</em>',intro:'The five milestones are implemented and validated. Knowing what the results do—and don’t—prove is part of understanding the system.',time:'6 MIN',question:'What can we conclude from the 1.492-second cached-fork median?',answers:['All databases fork in 1.492 seconds.','This workflow had that median across 19 cached forks in the recorded million-row demo.','APFS uses exactly 19 times less physical space.'],correct:1,explanation:'Measurements belong to a workload, machine, and method. This run used a roughly 341 MB application database, uncontrolled filesystem cache, and a small fixed-order sample.'}
};for(const l of lessons)Object.assign(l,data[l.id]||{})}
const external=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`;
function renderLesson(id){switch(id){
case 'queries': return lab('02 / THE QUERY WORKBENCH',`<pre>SELECT sum(balance) FROM accounts WHERE balance &lt; 100;</pre><div class="controls"><button class="primary" id="scan-all" aria-pressed="true">Sequential scan</button><button id="scan-index" aria-pressed="false">Use a balance index</button></div><div class="page-grid" id="query-pages" aria-label="Illustrative scan diagram"></div><div class="legend"><span><i class="dim"></i>Inspected table page</span><span><i></i>Page with a match</span></div><div id="query-feedback" class="feedback" role="status"></div><small class="muted">48 illustrative table pages, with 4 matching pages. This picture is not the demo’s real query plan or a timing model. Index traversal and visibility work are omitted.</small>`)+`<section class="two-col prose"><div><h2>What’s actually on disk?</h2><p>A <strong>table</strong> holds rows; its <strong>schema</strong> defines columns, types, and constraints. A primary key identifies a row. A foreign key connects it to an existing row in another table.</p><p>PostgreSQL stores table and index data in fixed-size <strong>pages</strong> (normally 8 KiB). Pages move between files and memory buffers. A row is a logical record; a page is a unit of storage. They are not the same thing.</p></div><div class="callout"><span class="overline">WHY AN INDEX HELPS</span><h3>A shortcut with a price.</h3><p>A B-tree index maintains an ordered search structure. It can narrow down matching keys rather than visiting every table row. It uses extra space and adds work when indexed data changes.</p><p>If most rows match, scanning the table may be cheaper. PostgreSQL’s planner estimates the costs; an index is not an automatic win.</p></div></section><section class="prose"><h2>Follow a query through the engine.</h2><p>The parser checks SQL structure. Planning chooses a strategy: scan a table, traverse an index, join results, aggregate. Execution visits the required data and applies transaction visibility rules. Buffers may already hold the pages, so a page visit does not always mean a physical disk read.</p><pre>CREATE INDEX accounts_balance_idx ON accounts (balance);
ANALYZE accounts;
EXPLAIN (ANALYZE, BUFFERS)
SELECT sum(balance) FROM accounts WHERE balance &lt; 100;</pre><p><code>ANALYZE</code> refreshes statistics used by the planner. <code>EXPLAIN ANALYZE</code> actually runs the query and reports observed work and timing. <code>BUFFERS</code> helps distinguish cached-page hits from reads.</p><p>The million-row Forklift demo changed from a parallel sequential scan to an <strong>index-only scan</strong>. PostgreSQL can sometimes answer using the index’s values and visibility information without fetching each table row. The result stayed the same.</p></section><details><summary>Where do MVCC and VACUUM fit?</summary><p>PostgreSQL uses multiple row versions to let transactions see appropriate snapshots while other transactions change data. An UPDATE can create a new row version instead of immediately destroying the old one. VACUUM reclaims space from versions no transaction still needs and maintains visibility information. These are PostgreSQL responsibilities, not features implemented by Forklift.</p></details><div class="source-links">${external('https://www.postgresql.org/docs/17/indexes-intro.html','PostgreSQL: indexes')}${external('https://www.postgresql.org/docs/17/storage-page-layout.html','PostgreSQL: pages')}${external('https://www.postgresql.org/docs/17/mvcc-intro.html','PostgreSQL: MVCC')}${source('docs/milestone-five.md','The actual query experiment')}</div>`;
case 'transactions':return lab('03 / A DURABLE TRANSFER',`<p>Transfer 100 from account A to account B. Step through the simplified ordering, or crash the model at any point.</p><div class="steps" id="wal-steps"></div><div class="table-wrap"><table><thead><tr><th>Where you look</th><th>Account A</th><th>Account B</th></tr></thead><tbody id="wal-values"></tbody></table></div><div class="controls"><button class="primary" id="wal-next">Begin & change balances</button><button id="wal-crash">Crash & recover</button><button id="wal-reset">Restart model</button></div><div class="feedback" id="wal-feedback" role="status"></div><small class="muted">Conceptual model. Real WAL has many record types; a data page may be written before commit after its WAL is flushed. Here we choose a valid, simpler schedule.</small>`)+`<section class="two-col prose"><div><h2>All of it, or none of it.</h2><p>A <strong>transaction</strong> groups changes into one unit. In this transfer, debiting A without crediting B would break the intended rule. <code>BEGIN</code> opens the transaction; <code>COMMIT</code> publishes success; <code>ROLLBACK</code> cancels it.</p><p>Other transactions do not see these uncommitted balance changes. Their precise view after a commit depends on their isolation level and snapshot.</p></div><div class="callout"><span class="overline">WRITE-AHEAD LOGGING</span><h3>Write the recovery record first.</h3><p>WAL is PostgreSQL’s durable change log. The relevant WAL must be flushed before changed data pages reach disk. With normal synchronous commit, success is acknowledged after the transaction’s commit record is durable.</p><p>On restart, PostgreSQL can redo work from WAL. A commit does not require flushing every changed table page immediately.</p></div></section><section class="prose"><h2>Four useful promises: ACID.</h2><div class="glossary"><div><h3>Atomicity</h3><p>The transaction’s changes become effective together, or not at all.</p></div><div><h3>Consistency</h3><p>Declared constraints are enforced. Your application still has to define and preserve its business rules.</p></div><div><h3>Isolation</h3><p>Concurrent transactions have controlled visibility. The strength depends on the chosen isolation level.</p></div><div><h3>Durability</h3><p>Acknowledged commits survive a process crash under the configured durability guarantees and functioning storage.</p></div></div></section><section class="prose"><h2>Two meanings of “checkpoint.”</h2><p>A <strong>PostgreSQL checkpoint</strong> flushes database state and establishes a recovery starting point. It does not turn a running data directory into a safe file-copy snapshot.</p><p>A <strong>Forklift checkpoint</strong> is a named immutable saved cluster. Forklift cleanly stops its source, captures it, and resumes it if it was running. The interruption is real and measured.</p><p>Forklift keeps <code>fsync</code>, <code>synchronous_commit</code>, and <code>full_page_writes</code> enabled, with page checksums. Turning durability off would change the experiment’s guarantees. Losing the whole disk still requires an independent backup to recover.</p></section><div class="source-links">${external('https://www.postgresql.org/docs/17/tutorial-transactions.html','PostgreSQL: transactions')}${external('https://www.postgresql.org/docs/17/wal-intro.html','PostgreSQL: WAL')}${source('docs/lifecycle.md','Forklift lifecycle guarantees')}</div>`;
case 'cow':return lab('04 / THE BLOCK SHARING MODEL',`<label class="range-label" for="changed-blocks">Blocks changed in branch A <output id="changed-count">0 / 8</output></label><input type="range" id="changed-blocks" min="0" max="8" value="0" step="1"><div id="cow-diagram"></div><div class="feedback" id="cow-feedback" role="status"></div><small class="muted">Idealized equal-size blocks: no filesystem metadata, compression, WAL, or write amplification. These counts are not measurements of APFS space.</small>`)+`<section class="two-col prose"><div><h2>Identity and bytes are different.</h2><p>An APFS clone has its own file identity. Initially, it can refer to the same physical blocks as the source. If one file changes a shared block, the filesystem preserves the other file’s bytes and gives the writer separate storage.</p><p>Branch isolation comes from this copy-on-write behavior. A hard link would point at the same mutable file and is therefore not an acceptable substitute.</p></div><div class="callout"><span class="overline">A USEFUL COST MODEL</span><h3>Pay for the differences.</h3><p>For two identical files of size S, full copying uses roughly 2S bytes of file content. An ideal copy-on-write model starts near S and adds changed blocks. Real systems include metadata and other costs.</p><p>More writes mean more divergence and less sharing. A long-lived, heavily modified branch can become expensive.</p></div></section><section class="prose"><h2>Fast copying is only one stage.</h2><p>Before cloning, Forklift checks ownership, paths, exact file lengths, SHA-256 hashes, and clean shutdown of the cache. Reading every cached file is work proportional to its size. It then clones and synchronizes destination files before publication.</p><p>The first fork must also reconstruct the cache from compressed objects. Later forks reuse it, but still verify it. A million-row warm reset recorded <strong>1.304 seconds of verification</strong> and <strong>0.118 seconds of clone/sync plus destination checks</strong>. Those are stages of one reset, not universal timings.</p><p>The explicit full-copy path is <code>--copy-mode full</code>. <code>--no-cache</code> reconstructs directly from objects. A missing clone capability is reported; it is not silently replaced by a full copy and called an APFS result.</p></section><details><summary>Why can’t “allocated bytes” tell us the exact savings?</summary><p>Ordinary per-file counters may count shared extents once for each file that references them. Summing them can count the same physical storage repeatedly. Apparent bytes describe logical file lengths. Neither number proves unique physical APFS consumption. Exact savings and peak space remain unmeasured.</p></details><div class="source-links">${source('src/storage.rs','Clone and sync implementation')}${source('docs/checkpoint-format.md','Verification and accounting contract')}${source('docs/milestone-five.md','Measured reset stages')}</div>`;
case 'objects':return lab('05 / CONTENT, ADDRESSED BY CONTENT',`<p>Two tiny illustrative files share the middle chunk. Change that chunk in file B and watch reuse change.</p><div id="object-diagram"></div><div class="controls"><button class="primary" id="object-change">Change B’s middle chunk</button><button id="object-corrupt">Corrupt a stored chunk</button><button id="object-restore">Verify & reconstruct</button><button id="object-reset">Reset model</button></div><div class="feedback" id="object-feedback" role="status">Three distinct chunks can describe six chunk references. Repeated content only needs one stored identity.</div><small class="muted">Short labels stand in for full SHA-256 hashes. Chunks here are symbols; real chunks are up to 1 MiB, collected in up-to-4 MiB uncompressed payloads.</small>`)+`<section class="two-col prose"><div><h2>A manifest is the recipe.</h2><p>For each file, the manifest records its relative path, length, whole-file hash, and ordered chunk hashes. A chunk index maps each hash to a pack, offset, and length. Directories and compatibility information are recorded too.</p><p>A <strong>hash</strong> is a deterministic digest of bytes. It lets the system identify repeated content and detect changes during verification. Identical content can be reused across captures.</p></div><div class="callout"><span class="overline">THREE DIFFERENT TECHNIQUES</span><h3>Reuse, shrink, share.</h3><p><strong>Deduplication:</strong> store repeated content once by hash.<br><strong>Compression:</strong> encode new pack content with fewer bytes using zstd.<br><strong>APFS cloning:</strong> share physical blocks between separate local files.</p><p>They operate at different layers. The object repository is currently a local directory, not S3.</p></div></section><section class="prose"><h2>The complete path from save to query.</h2><pre>running source
  → clean shutdown → chunk + hash → compressed packs
  → durable manifest → checkpoint published ready

checkpoint objects
  → reconstruct + verify → stopped cache
  → verify cache → APFS clone + sync → parked branch
  → explicit start → PostgreSQL reads normal local files</pre><p>The cache never runs as a database. On a valid hit, its ownership, file set, lengths, hashes, and shutdown state are checked. Ordinary corruption is quarantined and rebuilt; unsafe links or ownership mismatches fail closed.</p><p>New object data becomes durable before a manifest is published, and the catalog advertises readiness last. An interrupted capture must never appear to be a completed checkpoint.</p></section><section class="prose"><h2>“Portable” has a precise boundary.</h2><p>Export bundles the manifest and all required packs; restore validates and materializes them into a new stopped branch. It checks hashes, bounded lengths, paths, compatibility, clean shutdown, and PostgreSQL page checksums.</p><p>The current contract requires the same PostgreSQL reported version, <code>pg_config --configure</code> output, OS, and architecture. It is stricter than “any PostgreSQL 17.” Independent-store restore was tested on the same Mac; cross-machine and cross-OS portability were not demonstrated.</p><p>Only built-in <code>plpgsql</code> 1.0 is supported. External tablespaces, preloaded libraries, and arbitrary extension installation are outside v1. A hash detects corruption; it does not authenticate who made a bundle. Treat exports and SQL dumps as trusted inputs.</p></section><div class="source-links">${source('docs/checkpoint-format.md','Full format and validation contract')}${source('src/objects.rs','Object repository')}${source('src/cache.rs','Cache implementation')}</div>`;
case 'lifecycle':return lab('06 / THE RUNNING-CLUSTER BUDGET',`<div class="range-label"><span>Active clusters in this store</span><strong id="active-count">0 / 3</strong></div><div class="table-wrap"><table><thead><tr><th>Branch</th><th>State</th><th>Action</th></tr></thead><tbody id="lifecycle-rows"></tbody></table></div><div class="feedback" id="lifecycle-feedback" role="status">Start three branches, then try the fourth. Every parked branch already has saved files.</div><small class="muted">Simulation with four representative branches. No PostgreSQL processes are launched.</small>`)+`<section class="two-col prose"><div><h2>Parked is not paused RAM.</h2><p>A parked branch is persistent database files with no running PostgreSQL server. Stopping ends sessions and shuts the server down. Starting launches PostgreSQL against those files; it does not restore an old client session.</p><p>The default budget is three active clusters per store. It is not a host-wide cap, and it is not a count of every worker process. Each server can have several processes.</p></div><div class="callout"><span class="overline">WHY MAKE START EXPLICIT?</span><h3>Keep compute under control.</h3><p>Many stored experiments should not quietly consume the resources of many running databases. Connecting to a parked branch does not wake it. Automatic activation would need a proxy and additional lifecycle rules.</p></div></section><section class="prose"><h2>A real command sequence.</h2><p>These are implemented CLI commands. Assume <code>forklift</code> and compatible PostgreSQL 17 binaries are on your PATH. Use a new store path; a fresh <code>source</code> starts empty.</p><pre>forklift --home .forklift-tutorial init source
forklift --home .forklift-tutorial start source
# Load your own trusted fixture through the returned endpoint:
forklift --home .forklift-tutorial connection source
forklift --home .forklift-tutorial checkpoint source --name seed
forklift --home .forklift-tutorial branch --from seed --name experiment
forklift --home .forklift-tutorial start experiment
# Make SQL changes in experiment, then discard them:
forklift --home .forklift-tutorial reset experiment --to seed --yes
forklift --home .forklift-tutorial stop experiment
forklift --home .forklift-tutorial stop source</pre><p>The <code>--yes</code> on reset acknowledges replacement of that branch’s later data. Reset preserves its previous running/parked state. Export uses <code>export seed --output seed.forklift</code>; restore uses <code>restore seed.forklift --name restored</code>. The export destination must be new.</p></section><details><summary>How does external data enter Forklift?</summary><p><code>import NAME --dump FILE --yes</code> replaces a branch using a trusted custom or tar pg_dump archive. It restores into the postgres database with one restore transaction, without importing roles or ownership/privileges. It is a logical import into a fresh cluster, not copying an arbitrary live PGDATA directory.</p></details><details><summary>What if internal work needs a running slot?</summary><p>Imports count toward the budget. At capacity, an import into a running target can reuse its slot by stopping that target first. A checkpoint of a parked branch briefly needs a slot to inspect extensions. Recovery that needs to restart a branch can remain pending when capacity is full; stopping another branch or raising the limit allows progress.</p></details><div class="source-links">${source('docs/lifecycle.md','Every command, state, and error')}${source('src/bin/forklift.rs','CLI definitions')}</div>`;
case 'recovery':return lab('07 / INTERRUPT A RESET',`<p>The branch currently points to generation 17. A reset is building generation 18 from a saved checkpoint.</p><label class="range-label" for="crash-stage">Choose where the command dies <output id="crash-label"></output></label><input type="range" id="crash-stage" min="0" max="3" value="0"><div class="steps" id="reset-steps"></div><div class="root-node" id="catalog-pointer">catalog: experiment → generation 17</div><div class="controls"><button class="primary" id="reset-crash">Crash & run reconciliation</button></div><div class="feedback" id="reset-feedback" role="status">Move the slider across the catalog switch. Predict which complete generation remains selected.</div><small class="muted">A model of the documented protocol, not a running failpoint test. Assume a previously running target and available capacity for recovery.</small>`)+`<section class="two-col prose"><div><h2>Names need an authority.</h2><p>The catalog is a small versioned JSON file linking branch names to generations, checkpoint ancestry, process identity, and pending work. A <strong>generation</strong> is a separate owned directory containing one cluster’s files.</p><p>A reset prepares and verifies a replacement without overwriting the current files. Once ready, it stops the old server, switches the catalog pointer, and resumes the branch if needed.</p></div><div class="callout"><span class="overline">THE COMMIT POINT</span><h3>One authoritative switch.</h3><p>Before the catalog switch, generation 17 is selected. After it, generation 18 is selected. The system does not decide by guessing which directory looks newest.</p><p>Old and failed generations are retained. Safe garbage collection is future work.</p></div></section><section class="prose"><h2>Atomic and durable are different.</h2><p><strong>Atomic</strong> means readers see the old catalog or the new catalog, not half of each. <strong>Durable</strong> means the data has been synchronized with storage according to the platform’s guarantees. A rename alone is not the complete persistence protocol.</p><pre>write new catalog to a fresh temporary file
→ sync the file
→ rename it into place
→ sync its containing directory</pre><p>The next command reconciles interrupted operations against the catalog and observed process identity. Even <code>list</code> can finish reconciliation and resume a branch; it is not purely read-only. Recovery is not an automatic boot-time service.</p></section><section class="prose"><h2>Correctness includes process ownership.</h2><p>A PID is not enough: operating systems reuse process numbers. Forklift combines the PID with OS and PostgreSQL start information, pidfile directory/socket checks, and a SQL check of the connected data directory. On mismatch, it refuses to signal an unrelated process.</p><p>An exclusive store lock prevents two commands from claiming the last running slot or changing a branch simultaneously. Ownership markers and path validation constrain file operations to the managed store.</p><div class="table-wrap"><table><thead><tr><th>Failure</th><th>Responsible mechanism</th></tr></thead><tbody><tr><td>PostgreSQL process crashes</td><td>PostgreSQL WAL and transaction recovery</td></tr><tr><td>Forklift dies during reset</td><td>Catalog publication and reconciliation</td></tr><tr><td>Cache content is corrupted</td><td>Verification, quarantine, reconstruction</td></tr><tr><td>The whole disk is lost</td><td>Needs an independent backup; local mechanisms are insufficient</td></tr></tbody></table></div></section><div class="source-links">${source('src/storage.rs','Atomic catalog writes')}${source('docs/lifecycle.md','Recovery contract')}${source('docs/milestone-two.md','Interruption test evidence')}</div>`;
case 'code':return lab('08 / FOLLOW THE RESPONSIBILITIES',`<div class="file-tabs" id="file-tabs"></div><div id="file-detail"></div>`,'ACTUAL SOURCE EXCERPTS')+`<section class="two-col prose"><div><h2>Read this Rust first.</h2><p><code>struct</code> groups named fields. <code>enum</code> lists alternatives such as <code>Running</code> or <code>Stopped</code>. <code>impl</code> groups methods belonging to a type. <code>match</code> handles alternatives explicitly.</p><p><code>Result&lt;T, Error&gt;</code> means success containing T or a failure. <code>Option&lt;T&gt;</code> means a value may be present or absent. Neither is an exception thrown invisibly through the program.</p></div><div class="callout"><span class="overline">WHY RUST HERE?</span><h3>Explicit state. Native control.</h3><p>Rust gives this CLI strong types, memory safety, and access to filesystem and process APIs. That helps express boundaries, but it does not automatically prove crash consistency or speed.</p><p>PostgreSQL remains primarily C. This project is not a translation of its database engine into Rust.</p></div></section><section class="prose"><h2>Borrowing, without the mystery.</h2><p><code>&amp;Path</code> borrows a path so a function can use it without taking ownership. <code>&amp;mut</code> is an exclusive mutable borrow. Owned values are cleaned up when their owner goes out of scope. This prevents many memory bugs; it does not replace explicit <code>sync_all()</code> calls for durable files.</p><p><code>#[derive(Serialize, Deserialize)]</code> asks serde to generate data conversion code. <code>#[serde(deny_unknown_fields)]</code> makes a stored format reject unexpected fields. <code>pub</code> exposes an item outside its module. A generic <code>&lt;T&gt;</code> lets a function operate on more than one type.</p></section><section class="prose"><h2>Read the project in this order.</h2><ol><li><code>src/bin/forklift.rs</code>: how a command becomes an operation.</li><li><code>src/lifecycle.rs</code>: catalog, ownership, state transitions, process management, recovery.</li><li><code>src/cache.rs</code>: validate or rebuild the stopped materialization.</li><li><code>src/objects.rs</code>: manifests, hashing, packing, export, and restore.</li><li><code>src/storage.rs</code>: low-level copies, APFS clones, synchronization, publication, and accounting.</li></ol><p><code>src/lib.rs</code> exposes these modules. <code>src/main.rs</code> is the original feasibility harness. <code>scripts/demo.py</code> drives the final reproducible demonstration; Python scripts also test real PostgreSQL lifecycle, objects, and caches.</p></section><details><summary>Which dependencies do the work?</summary><p><code>clap</code> parses the CLI; <code>serde</code> and <code>serde_json</code> serialize data; <code>sha2</code> computes hashes; <code>zstd</code> compresses packs; <code>libc</code> exposes native system calls. Versions are pinned in Cargo.toml and Cargo.lock. External PostgreSQL tools remain part of the runtime workflow.</p></details><details><summary>How do I run the checks?</summary><pre>cargo fmt --check
cargo test --locked
cargo clippy --locked --all-targets --all-features -- -D warnings
cargo build --locked --features test-failpoints
python3 scripts/test_lifecycle.py
python3 scripts/test_objects.py</pre><p>Integration checks need compatible native PostgreSQL and permissions for its shared memory. They create owned test stores. The optional <code>test-failpoints</code> feature injects abrupt exits at protocol boundaries; use the normal release build for real workflow measurements. See the lifecycle guide for cache checks and cleanup behavior.</p></details><div class="source-links">${source('Cargo.toml','Pinned dependencies')}${source('docs/lifecycle.md','Complete testing instructions')}</div>`;
case 'evidence':return lab('09 / READ THE MEASUREMENTS',`<label for="dataset">Recorded demo fixture &nbsp;</label><select id="dataset"><option value="million">1,000,000 rows</option><option value="smoke">100,000 rows</option></select><div id="measurements"></div><small class="muted">Recorded Oct 8, 2026 · Apple M4 · 16 GiB RAM · macOS 26.6.2/APFS · PostgreSQL 17.11. Changing this selector displays an existing run; it does not run a benchmark.</small>`,'RECORDED RESULTS')+`<section class="prose"><h2>What the five milestones answered.</h2><div class="table-wrap"><table><thead><tr><th>Milestone</th><th>Question answered</th><th>Status</th></tr></thead><tbody><tr><td>01 · Feasibility</td><td>Can stopped clones run independently with correct data?</td><td>Validated</td></tr><tr><td>02 · Lifecycle</td><td>Can names, processes, resets, and interruptions be managed?</td><td>Validated</td></tr><tr><td>03 · Objects</td><td>Can saved content be verified, exported, and restored?</td><td>Validated</td></tr><tr><td>04 · Many branches</td><td>Can 100 stored experiments coexist with bounded active servers?</td><td>Validated</td></tr><tr><td>05 · Reproducible demo</td><td>Can index, schema, deletion, reset, and independent restore be demonstrated?</td><td>Validated</td></tr></tbody></table></div></section><section class="two-col prose"><div><h2>Implemented.</h2><p>Local offline PostgreSQL experiments; parked and running branches; immutable object checkpoints; verified cached APFS clones; explicit full-copy and direct-object paths; a configurable running limit; export/restore; interruption recovery.</p><p>The 100-branch benchmark saved a distinct marker in every branch, restarted each, and verified it. The final demo used 20 experiment branches, plus its source and independent restore. These are different runs.</p></div><div class="callout"><span class="overline">FUTURE / NOT IMPLEMENTED</span><h3>Keep the boundary visible.</h3><p>No merge, live snapshot capture, per-branch delete, garbage collection, automatic startup on connection, cloud service, or object-backed query engine. No high availability or production tenant isolation.</p><p>Linux support, larger-scale work, safe cleanup, and deeper comparisons need separate engineering and evidence.</p></div></section><section class="prose"><h2>What the numbers cannot prove.</h2><p>These are small, fixed-order samples, not cold-disk or production capacity tests. The OS filesystem cache was uncontrolled. Source interruption belongs in the workflow cost: the million-row source checkpoint interrupted its server for <strong>7.031 seconds</strong>.</p><p>The query’s 21.853 ms to 0.068 ms change is a PostgreSQL index effect for this selective query. It is not a Forklift storage multiplier. The small-fixture cached full-copy baseline in milestone four was similar to APFS clone latency.</p><p>The final million-row store reported <strong>17.962 GB apparent</strong> and <strong>17.964 GB allocated block counts</strong>. Neither identifies unique physical APFS space. Cache files, old generations, WAL, and retained failed work count. Exports are separate.</p><p>Three active clusters had 18 processes and 94.516 MiB summed RSS in one observation. Shared memory may be counted multiple times; OS filesystem cache memory is excluded. Parked snapshots had no PostgreSQL processes.</p><p>Process interruption and WAL recovery were tested. Host power loss, disk loss protection, exact shared-space savings, cross-machine restore, and performance superiority over Neon or DBLab were not demonstrated.</p></section><section class="prose"><h2>The whole system, in one sentence.</h2><p>Forklift combines unmodified PostgreSQL, a durable lifecycle catalog, verified local file clones, and portable saved-state objects to make local database experiments easier to repeat and reason about.</p><p>Its contribution is the workflow and correctness machinery around established storage techniques. A custom storage engine was not needed to finish these five milestones.</p></section><details><summary>Your pocket glossary</summary><dl class="glossary"><div><dt>Branch</dt><dd>A named, independently writable whole PostgreSQL cluster.</dd></div><div><dt>Generation</dt><dd>One physical data directory selected by a branch’s catalog entry.</dd></div><div><dt>Checkpoint</dt><dd>In Forklift, immutable saved cluster contents.</dd></div><div><dt>Manifest</dt><dd>The metadata recipe mapping paths to ordered content chunks.</dd></div><div><dt>Materialization</dt><dd>Reconstructing normal files from a saved recipe.</dd></div><div><dt>WAL</dt><dd>PostgreSQL’s write-ahead log for crash recovery.</dd></div><div><dt>Copy-on-write</dt><dd>Sharing unchanged storage until one independent file changes it.</dd></div><div><dt>Reconciliation</dt><dd>Resolving recorded intermediate state against actual files and processes.</dd></div></dl></details><div class="source-links">${source('docs/milestone-five.md','Consolidated measured report')}${source('results/2026-10-08-demo/million/report.md','Million-row evidence')}${source('results/2026-10-08-demo/smoke/report.md','100k-row evidence')}${source('docs/milestone-four.md','Separate 100-branch benchmark')}${source('docs/demo.md','Reproduce the demo')}${source('PROJECT_PLAN.md','Plan and deferred scope')}</div>`;
default:return ''}}
const codeFiles=[
{name:'CLI',path:'src/bin/forklift.rs',title:'Turn intent into an operation.',description:'clap derives the parser from Args and Action. The CLI opens the store, applies cache preferences, reconciles interrupted work, then dispatches the requested operation. The ? operator returns early on failure.',code:'s.set_cache_enabled(!args.no_cache);\ns.reconcile()?;\nmatch &args.command {\n    Action::Init { name } => s.init(name)?,',note:'Excerpt from execute(); the match continues with the other commands.'},
{name:'Lifecycle',path:'src/lifecycle.rs',title:'Make branch state explicit.',description:'A Branch has a selected head generation, optional checkpoint ancestry, optional pending replacement, and recovery intent. Option means “may be absent.” Keeping a pending replacement separate from head is central to safe publication.',code:'struct Branch {\n    head: Instance,\n    checkpoint: Option<String>,\n    pending: Option<Instance>,\n    resume: bool,',note:'Opening fields of Branch; additional metadata fields follow.'},
{name:'Objects',path:'src/objects.rs',title:'Describe files using content identities.',description:'FileEntry records a safe relative path, total length, whole-file SHA-256, and an ordered vector of chunk hashes. The manifest’s chunk map supplies the pack locations. A Vec is Rust’s growable sequence.',code:'pub struct FileEntry {\n    pub path: String,\n    pub length: u64,\n    pub sha256: String,\n    pub chunks: Vec<String>,\n}',note:'The actual file-entry structure. Serialization derives appear immediately above it.'},
{name:'Cache',path:'src/cache.rs',title:'Verify before trusting a shortcut.',description:'The cache first validates the filesystem tree, then verifies all materialized content against the manifest. A valid result still needs a clean shutdown check. Content corruption is handled by quarantine and reconstruction in later match arms.',code:'validate_tree(&data)?;\nmatch objects::verify_materialized(&manifest, &data) {\n    Ok(()) => {\n        check_stopped(&data)?;',note:'Excerpt from prepare(); event recording and error handling follow.'},
{name:'Storage',path:'src/storage.rs',title:'The ordering is the algorithm.',description:'atomic_json writes a new temporary file. These final steps synchronize its data, rename it into place, then synchronize the directory. Memory safety cannot substitute for this persistence ordering.',code:'f.write_all(&serde_json::to_vec_pretty(value)?)?;\nf.write_all(b"\\n")?;\nf.sync_all()?;\nfs::rename(&tmp, path)?;\nsync_dir(path.parent().unwrap())',note:'The closing sequence of atomic_json<T: serde::Serialize>().'}
];
let walStage=0,walRecovered=false,objectChanged=false,objectCorrupt=false,activeBranches=[false,false,false,false];
function bindLesson(id){switch(id){
case 'queries':$('#scan-all').onclick=()=>queryScan(false);$('#scan-index').onclick=()=>queryScan(true);queryScan(false);break;
case 'transactions':walStage=0;walRecovered=false;$('#wal-next').onclick=()=>{walStage=Math.min(3,walStage+1);walDraw()};$('#wal-crash').onclick=()=>{walRecovered=true;walDraw()};$('#wal-reset').onclick=()=>{walStage=0;walRecovered=false;walDraw()};walDraw();break;
case 'cow':$('#changed-blocks').oninput=cowDraw;cowDraw();break;
case 'objects':objectChanged=false;objectCorrupt=false;$('#object-change').onclick=()=>{objectChanged=!objectChanged;objectDraw();$('#object-feedback').textContent=objectChanged?'File B now references D instead of B. The old B chunk remains available to file A and earlier saves. Four unique chunks now serve six references.':'Both files reference A, B, C again. Three reachable chunk identities serve six references; a real store can retain the now-unused D because it has no garbage collection.'};$('#object-corrupt').onclick=()=>{objectCorrupt=true;objectDraw();$('#object-feedback').textContent='Stored bytes for chunk A no longer match its expected hash. Try verification. A checksum should detect this, not quietly accept it.'};$('#object-restore').onclick=()=>{$('#object-feedback').textContent=objectCorrupt?'Restore refused: chunk A’s bytes do not match its hash. This destination is not published as a ready branch. Existing valid branches stay selected.':'Verification passed: the referenced chunk identities match their bytes. The files can be reconstructed in manifest order. Real restore also validates packs, file hashes, paths, compatibility, shutdown, and page checksums.'};$('#object-reset').onclick=()=>{objectChanged=false;objectCorrupt=false;objectDraw();$('#object-feedback').textContent='Model reset: three unique chunks, six references, no corruption.'};objectDraw();break;
case 'lifecycle':activeBranches=[false,false,false,false];lifecycleDraw();break;
case 'recovery':$('#crash-stage').oninput=resetDraw;$('#reset-crash').onclick=()=>{const n=Number($('#crash-stage').value);$('#reset-feedback').textContent=n<3?'Recovered generation 17. The catalog never selected 18, so pending work cannot replace the original. If the old server was stopped, reconciliation resumes it when capacity is available.':'Recovered generation 18. The catalog switch committed the replacement. Reconciliation resumes that selected generation when capacity is available. Generation 17 is retained, not silently selected again.'};resetDraw();break;
case 'code':$('#file-tabs').innerHTML=codeFiles.map((f,i)=>`<button data-file="${i}" aria-pressed="${i===0}">${f.name}</button>`).join('');document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>codeDraw(Number(b.dataset.file)));codeDraw(0);break;
case 'evidence':$('#dataset').onchange=evidenceDraw;evidenceDraw();break;
}}
function queryScan(index){const matches=[5,17,29,41];$('#query-pages').innerHTML=Array.from({length:48},(_,i)=>`<span class="page-cell ${matches.includes(i)?'match':index?'':'scanned'}"></span>`).join('');$('#scan-all').classList.toggle('primary',!index);$('#scan-index').classList.toggle('primary',index);$('#scan-all').setAttribute('aria-pressed',String(!index));$('#scan-index').setAttribute('aria-pressed',String(index));$('#query-feedback').textContent=index?'The index narrows the candidate locations. In this toy picture, 4 matching table pages are highlighted; index traversal and visibility checks are extra work. The query’s answer is unchanged.':'Sequential scan: inspect all 48 illustrative table pages and filter rows by balance. Only 4 pages contain a match. Most of the inspected data doesn’t contribute to the answer.'}
function walDraw(){const labels=['Initial state','Changes pending','Commit durable','Data pages flushed'];$('#wal-steps').innerHTML=labels.map((s,i)=>`<div class="step ${i===walStage?'active':''}"><small>0${i+1}</small>${s}</div>`).join('');const committed=walStage>=2;const transaction=walRecovered?(committed?[900,1100]:[1000,1000]):walStage>0?[900,1100]:[1000,1000];const disk=walStage===3||walRecovered&&committed?[900,1100]:[1000,1000];$('#wal-values').innerHTML=`<tr><td>${walRecovered?'After recovery':'Transaction’s view'}</td><td>${transaction[0]}</td><td>${transaction[1]}</td></tr><tr><td>Data pages on disk</td><td>${disk[0]}</td><td>${disk[1]}</td></tr><tr><td>Durable commit record</td><td colspan="2">${committed?'Yes':'No'}</td></tr>`;$('#wal-next').disabled=walRecovered||walStage===3;$('#wal-crash').disabled=walRecovered;$('#wal-next').textContent=['Begin & change balances','Flush WAL & commit','Flush data pages','All steps complete'][walStage];$('#wal-feedback').textContent=walRecovered?(committed?'The transfer survives. Its commit was durable, so recovery can redo required changes from WAL even if table pages were old. A = 900, B = 1,100.':'The transfer was not committed. Recovery leaves no visible partial transfer. A = 1,000, B = 1,000.'):['Both accounts have 1,000. No transfer has begun.','The transaction sees A = 900 and B = 1,100, but has not committed. Other transactions cannot see this incomplete transfer.','The commit record is durable. Success can be acknowledged even while data pages on disk still show the old balances. Try crashing now.','The changed data pages are now flushed too. WAL remains part of PostgreSQL’s recovery machinery.'][walStage]}
function cowDraw(){const n=Number($('#changed-blocks').value);$('#changed-count').textContent=`${n} / 8`;$('#cow-diagram').innerHTML=['Source','Branch A','Branch B'].map((name,row)=>`<div class="block-row"><span>${name}</span>${Array.from({length:8},(_,i)=>`<div class="block ${row===1&&i<n?'changed':''}">${row===1&&i<n?'Δ':String.fromCharCode(65+i)}</div>`).join('')}</div>`).join('');$('#cow-feedback').textContent=`Idealized unique block versions: ${8+n}, versus 24 for three full copies. Branch A shares ${8-n} of its 8 blocks; Source and Branch B keep the original bytes. ${n===0?'Move the slider to write into Branch A.':'Identical letters denote shared originals; Δ denotes a private changed version in A.'}`}
function objectDraw(){const files=[['file A',['A','B','C']],['file B',['A',objectChanged?'D':'B','C']]];$('#object-diagram').innerHTML=files.map(([name,chunks])=>`<div class="block-row"><span>${name}</span>${chunks.map(c=>`<span class="block ${c==='D'?'changed':''}">${c}</span>`).join('')}<small class="muted">ordered references</small></div>`).join('')+`<div class="block-row"><span>Stored content</span>${['A','B','C',...(objectChanged?['D']:[])].map(c=>`<span class="block ${c==='A'&&objectCorrupt?'bad':''}">${c==='A'&&objectCorrupt?'A ≠ hash':c}</span>`).join('')}</div>`}
function lifecycleDraw(){const count=activeBranches.filter(Boolean).length;$('#active-count').textContent=`${count} / 3`;$('#lifecycle-rows').innerHTML=['add-index','change-schema','delete-rows','agent-test'].map((n,i)=>`<tr><td><code>${n}</code></td><td><span class="status-chip">${activeBranches[i]?'RUNNING':'PARKED'}</span></td><td><button data-toggle="${i}">${activeBranches[i]?'Stop':'Start'} ${n}</button></td></tr>`).join('');document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.toggle);if(!activeBranches[i]&&activeBranches.filter(Boolean).length>=3){$('#lifecycle-feedback').textContent='running_limit: all three slots are occupied. Stop one branch before starting another. The fourth branch’s saved files are still intact.';return}activeBranches[i]=!activeBranches[i];lifecycleDraw();$('#lifecycle-feedback').textContent=activeBranches[i]?'Started: this branch now has an active server. Its files existed while it was parked.':'Parked: the server is stopped and its sessions are gone, but the database files and committed data remain.'})}
function resetDraw(){const n=Number($('#crash-stage').value);const names=['Building 18','18 verified + synced','Old server stopped','Catalog switched'];$('#crash-label').textContent=names[n];$('#reset-steps').innerHTML=names.map((x,i)=>`<div class="step ${i===n?'active':''}"><small>0${i+1}</small>${x}</div>`).join('');$('#catalog-pointer').textContent='catalog: experiment → generation '+(n===3?'18':'17');$('#reset-feedback').textContent=n===3?'The durable catalog now selects generation 18. What should the next command resume if we crash here?':'Generation 18 has not been published. The catalog still selects generation 17. Crash here to inspect recovery.'}
function codeDraw(i){const f=codeFiles[i];document.querySelectorAll('[data-file]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.file)===i)));$('#file-detail').innerHTML=`<h3>${f.title}</h3><p>${f.description}</p><pre><code>${esc(f.code)}</code></pre><p style="font-size:13px">${f.note}</p><div class="source-links" style="color:#d2f36b">${source(f.path,'Open '+f.path)}</div>`}
function evidenceDraw(){const big=$('#dataset').value==='million';const d=big?{first:9.096,warm:1.492,reset:1.919,restore:10.194,before:21.853,after:.068,size:340.834,cache:776.447}:{first:5.050,warm:.380,reset:.835,restore:5.167,before:5.425,after:.022,size:41.220,cache:107.734};const max=Math.max(d.first,d.restore);$('#measurements').innerHTML=`<div class="metric-bars">${[['First fork',d.first],['Cached fork',d.warm],['Running reset',d.reset],['Portable restore',d.restore]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><i style="width:${v/max*100}%"></i></div><strong>${v.toFixed(3)} s</strong></div>`).join('')}</div><p style="font-size:13px">Whole CLI wall time. First fork includes cache construction (one observation). Cached fork is the median of 19 subsequent forks. Reset and restore: one observation each. Bars use a linear scale.</p><div class="table-wrap"><table><tbody><tr><td>Application database size</td><td>${d.size.toFixed(3)} MB</td></tr><tr><td>Stopped cache incl. WAL/system files</td><td>${d.cache.toFixed(3)} MB</td></tr><tr><td>Query before index · median of 5</td><td>${d.before.toFixed(3)} ms</td></tr><tr><td>Query after index · median of 5</td><td>${d.after.toFixed(3)} ms</td></tr></tbody></table></div><div class="feedback">The index changes PostgreSQL’s query plan. The cached fork changes the branch-creation workflow. These are two different kinds of performance.</div>`}
